package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactoryImpl;
import com.fasterxml.jackson.core.io.JsonLocation;
import com.fasterxml.jackson.core.io.JsonStreamReadException;
import com.fasterxml.jackson.core.io.TokenBuffer;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen0Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactoryImpl();
    }

    /**
     * Test case: Current token is already FIELD_NAME.
     * Should call _nextAfterName() and return false.
     */
    @Test
    public void testNextFieldName_WhenCurrentTokenIsFieldName() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        // Move to the first field name
        parser.nextToken(); 
        assertEquals(JsonToken.START_OBJECT, parser.currentToken());
        parser.nextToken();
        assertEquals(JsonToken.FIELD_NAME, parser.currentToken());

        // Calling nextFieldName when already on FIELD_NAME
        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("name");
        boolean result = parser.nextFieldName(sstr);

        assertFalse("Should return false when current token is FIELD_NAME", result);
    }

    /**
     * Test case: Happy path - successful match of field name using the fast-path logic.
     */
    @Test
    public void testNextFieldName_SuccessfulMatch() throws IOException {
        String json = "{\"target\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("target");
        boolean result = parser.nextFieldName(sstr);

        assertTrue("Should return true on successful match", result);
        // After nextFieldName returns true, the parser should be at the value token
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    /**
     * Test case: Field name match via the fallback method (_isNextTokenNameMaybe).
     */
    @Test
    public void testNextFieldName_FallbackMatch() throws IOException {
        String json = "{\"key\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        // Use a string that might not trigger the optimized buffer check but works via fallback
        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("key");
        boolean result = parser.nextFieldName(sstr);

        assertTrue("Should return true via fallback", result);
    }

    /**
     * Test case: Field name does not match.
     */
    @Test
    public void testNextFieldName_NoMatch() throws IOException {
        String json = "{\"wrong\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("target");
        boolean result = parser.nextFieldName(sstr);

        assertFalse("Should return false when name does not match", result);
    }

    /**
     * Test case: End of Array encountered when expecting a field name (mismatched context).
     * This tests the i == INT_RBRACKET branch.
     */
    @Test
    public void testNextFieldName_EndArrayInObjectContext() throws IOException {
        // The parser is in an object, but we encounter a ']' instead of a field name
        String json = "{\"a\": [1, 2] ]"; 
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // 1
        parser.nextToken(); // 2
        parser.nextToken(); // END_ARRAY

        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("any");

        try {
            parser.nextFieldName(sstr);
            fail("Should have thrown an exception due to mismatched end marker");
        } catch (JsonStreamReadException e) {
            // Expected behavior for mismatched markers
        }
    }

    /**
     * Test case: End of Object encountered when expecting a field name.
     * This tests the i == INT_RCURLY branch.
     */
    @Test
    public void testNextFieldName_EndObjectInObjectContext() throws IOException {
        String json = "{\"a\":1}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // 1

        // Now we are at the end of the object. 
        // Calling nextFieldName should see '}' and return false.
        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("a");
        boolean result = parser.nextFieldName(sstr);

        assertFalse(result);
        assertEquals(JsonToken.END_OBJECT, parser.currentToken());
    }

    /**
     * Test case: End of Input (EOF) encountered.
     * This tests the i < 0 branch.
     */
    @Test
    public void testNextFieldName_EndOfInput() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // END_OBJECT

        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("a");
        boolean result = parser.nextFieldName(sstr);

        assertFalse(result);
        assertNull(parser.currentToken());
    }

    /**
     * Test case: Calling nextFieldName when not in an Object context.
     * This tests the !_parsingContext.inObject() branch.
     */
    @Test
    public void testNextFieldName_NotInObject() throws IOException {
        String json = "[1, 2, 3]";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_ARRAY

        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("a");

        try {
            parser.nextFieldName(sstr);
            fail("Should have thrown an exception because we are in an array, not an object");
        } catch (Exception e) {
            // Expected: _nextTokenNotInObject is called
        }
    }

    /**
     * Test case: Check comma skipping.
     */
    @Test
    public void testNextFieldName_WithComma() throws IOException {
        String json = "{\"a\":1, \"b\":2}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // 1

        // Now at comma. nextFieldName should skip comma and find "b"
        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("b");
        boolean result = parser.nextFieldName(sstr);

        assertTrue(result);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    /**
     * Test case: Fast-path match failure due to character mismatch in buffer.
     */
    @Test
    public void testNextFieldName_FastPathMismatch() throws IOException {
        String json = "{\"abcde\":\"val\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        // Match "abcd" against "abcde"
        SerializableString sstr = JsonFactory.SerializableString.newSerializableString("abcd");
        boolean result = parser.nextFieldName(sstr);

        assertFalse(result);
    }
}
